// IContainer is an abstract interface to define a container of arbitrary data that can be passed
// to the machine that performs the build operation of a UJITSO processor
// The container does not have to be filled with the actual data until the build system determined that
// the associated build request needs to be built.
// Containers provide an abstract interface for serializing and deserializing the contents of the container.
// This is used to transport the data to a remote machine when the processor build happens remotely.
//
// A simple helper implementation VectorContainer that stores the data in a vector exists in ContainerUtils.h
//
// The interaction with the UJITSO build system works as follow:
//     Before issuing a request the user needs to create a new container instance
//     At this point the container doesn't need to be filled with data, it just needs to have a valid contentHash
//
//     The container needs to be registered with the carb::ujitso::IRegistry to retrieve a ContainerHandle
//
//     Now the user can embed the ContainerHandle inside the request and call agent->requestBuild.
//     
//     Inside the gatherDependencies function a processor can add the container to the dependencies.
//     It is very important to not add the ContainerHandle via addRequestTuple as this is non-deterministic.
//     At this point the content hash of the container must be provided in the container and it will become part of the compound input hash for the result of the build.
//
//     When the buildsystem determines that the current build result is not cached (based on the compound input hash), the container function fill() will be called.
//     Only if the build happens on a different machine the container function write() will also be called.
//
//     On the remote machine a factory that can create the container has to be registered with the IRegistry. The container will be created and then read() is called to fill it's contents.
//     Now the processor's build() function can obtain the container from the registry (via. the content hash) and then access its contents.
//

using ContainerType = uint64_t;
using ContainerContentHash = omni::hash128_t;
using ContainerContentHashPOD = omni::hash128POD_t;
class IReader;
class IWriter;

// Abstract data container interface for UJITSO build system
class IContainer : public omni::core::Inherits<omni::core::IObject, OMNI_TYPE_ID("carb.ujitso.IContainer")>
{
public:
    // Deferred fill of the container contents when building is required
    virtual void fill() = 0;
    // Deserialize the container contents after they were send over the wire
    // No refcounting operations are necessary on the reader
    virtual void read(IReader& reader) = 0;
    // Serialize the container contents for transport over the wire
    // No refcounting operations are necessary on the writer
    virtual void write(IWriter& writer) = 0;

    // Retrieve the name of the container, usually initialized via: UJITSO_CONTAINER_DEFINITION
    virtual const char* getName() const = 0;
    // Retrieve a hash describing the type, usually initialized via: UJITSO_CONTAINER_DEFINITION
    virtual ContainerType getType() const = 0;
    // Retrieve the container content hash, the needs to be filled even if the container hasn't been filled yet
    virtual ContainerContentHash getContentHash() const = 0;
};

// Abstract reader interface to read from a stream of binary data during container serialization
class IReader : public omni::core::Inherits<omni::core::IObject, OMNI_TYPE_ID("carb.ujitso.IReader")>
{
public:
    typedef void (*ReadCallback)(void* context, const uint8_t* data, size_t size);

    // Number of bytes left to read on this reader
    virtual size_t bytesLeft() = 0;
    // Synchronously read size bytes from the reader. The data buffer provided in the callback is only valid
    // during the callback. The context pointer is passed to the callback as is.
    virtual void read(size_t size, ReadCallback callback, void* context) = 0;
};

// Abtract binary data writer interface used to allow serialization of a container
class IWriter : public omni::core::Inherits<omni::core::IObject, OMNI_TYPE_ID("carb.ujitso.IWriter")>
{
public:
    // Synchronously write a number of bytes
    virtual void write(const void* data, size_t sizeInBytes) = 0;
};

